export function salesLabel(language:UiLanguage,english:string):string {
 return uiText(language,english,bangla[english]??english);
}
export function salesOptions(language:UiLanguage,values:readonly string[]){
 return values.map(value=>({value,label:salesLabel(language,value)}));
}
